WITH valid_departments AS (SELECT *, SUBSTRING(dept_name, 1, 4) AS dept_name_prefix FROM departments WHERE location IS NULL AND budget < 2503000), dept_name_group_summary AS (SELECT CASE WHEN dept_name IN ('Marketing', 'Finance') THEN 'tier_1' ELSE 'other' END AS dept_name_group, COUNT(*) AS row_count FROM valid_departments GROUP BY CASE WHEN dept_name IN ('Marketing', 'Finance') THEN 'tier_1' ELSE 'other' END) SELECT dept_name_group, row_count FROM dept_name_group_summary;
